+    root.replaceChildren(
+      h("header", { class: "topbar" }, h("h1", {}, "Malpaco"), h("span", { class: "subtitle" }, `Nine Isles · ${this.controller.state.players.length} human seats · Seed ${this.seed}`), score, footer),
