"""Probe: what happens if threshold drift is implemented (allowing armies below threshold to fight)."""
from pathlib import Path
import subprocess, sys

repo = Path("/home/diego/projects/malpaco-work/128-review-0711a802")
controller = repo / "src/ui/battleController.ts"
saved = controller.read_bytes()

# Write a test that checks source/stop behavior across many exchanges
test_file = repo / "tests/ui/battle-drift-temp.test.ts"
test_file.write_text("""
import { describe, it, expect } from "vitest";
import { BattleController, Clock, battle } from "./battle-fixtures";

describe("battle threshold drift", () => {
  it("threshold clamps to min(threshold, source - 1) at battle start and stays fixed", () => {
    const clock = new Clock(), c = new BattleController(battle(20, 20), clock);
    c.select("sulo", "frostkabo");
    c.setThreshold(2);
    expect(c.view.threshold).toBe(2);
    expect(c.view.effectiveThreshold).toBe(2);
    // After setting threshold, the effectiveThreshold should be clamped.
    // If a mutation allows "remembered but drift", threshold might not be clamped properly.

    // Now fightOn should use clamped threshold
    c.fightOn();
    expect(c.view.effectiveThreshold).toBe(2); // stays at 2 even after first exchange

    // The next exchange uses the same threshold
    clock.flush();

    // Source still has enough armies to fight; battle continues
    expect(c.state.armies["sulo"]).toBeGreaterThan(2);
  });
});
""")

unit = ["npx", "vitest", "run", "tests/ui/battle-drift-temp.test.ts"]

# Test base
result = subprocess.run(unit, cwd=repo, capture_output=True, timeout=60)
print("Base:", result.returncode)
print(result.stdout.decode()[-500:])

# Now try mutations to test threshold drift scenarios
mutations = [
    # Allow fightOn with threshold > available armies (drift)
    ("threshold_drift_fighton",
     "this.current = { ...this.current, effectiveThreshold: this.current.paused ? this.current.effectiveThreshold : this.clamp(), paused: false };",
     "this.current = { ...this.current, effectiveThreshold: this.current.paused ? this.current.effectiveThreshold : this.clamp(), paused: false };\n    void this.current.threshold;  // no change",
     0),  # no-op; informational
    # The threshold check should stop battle when armies drop to threshold
    ("no_threshold_stop",
     "const threshold = armyCount(result.state, from) <= this.current.effectiveThreshold;",
     "const threshold = false;",  # never stop on threshold
     1),
]

for label, needle, replacement, expected in mutations:
    needle_b = needle.encode()
    if needle_b not in saved:
        print(f"SKIP {label}")
        continue
    changed = saved.replace(needle_b, replacement.encode(), 1)
    try:
        controller.write_bytes(changed)
        result = subprocess.run(unit, cwd=repo, capture_output=True, timeout=60)
        # Use comprehensive test suite for these
        result_full = subprocess.run(["npx", "vitest", "run", "tests/ui/battle-controller.test.ts"], cwd=repo, capture_output=True, timeout=120)
        matched = (result_full.returncode != 0) == (expected != 0)
        print(f"{label:30s}: threshold-test={result.returncode} full-test={result_full.returncode} expected={expected} {'MATCH' if matched else 'MISMATCH'}")
    finally:
        controller.write_bytes(saved)

test_file.unlink()
PYEOF
